#include <cmath>
using namespace std;

int main() {
    long long x;
    cin >> x;
    long long total = -x;
    long long r;
    if (total >= 0) {
        r = total % 360;
    } else {
        r = (-total) % 360;
        r = (-r) % 360;
        if (r < 0) r += 360;
    }
    long long min_dev = 360;
    int best_k = 0;
    for (int k = 0; k < 4; k++) {
        long long angle = (r + 90LL * k) % 360;
        if (angle < 0) angle += 360;
        long long dev = min(angle, 360 - angle);
        if (dev < min_dev) {
            min_dev = dev;
            best_k = k;
        }
    }
    cout << best_k << endl;
    return 0;
}
